 44	     * @var list<string>
 45	     */
 46	    private const EMAIL_DOMAINS = [
 47	        'orbitmail.net',
 48	        'stellarbox.com',
 49	        'voidpost.org',
 50	        'galaxypost.net',
 51	        'cometmail.com',
 52	    ];
