 60	        'New Terra',
 61	        'Outpost',
 62	        'Haven',
 63	        'Frontier',
 64	        'Aurora',
 65	        'Base Camp',
 66	        'Sunrise',
 67	        'Anchor',
 68	        'Redoubt',
 69	        'Waystation',
 70	    ];
