 45	     */
 46	    private function capacityByPrice(PlanetService $planet): array
 47	    {
 48	        $candidates = [];
 49	
 50	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
 51	            if (!BuildingQueueObject::accepts($object->machine_name)) {
